use std::f64::consts::PI;

use super::*;
use crate::geom::inv;
use crate::involute::{Involute, mesh_external};
use crate::plan::{Kind, Spec, plan};

fn close(a: f64, b: f64, rel: f64) -> bool {
    ((a - b) / b).abs() <= rel
}

/// ISO 6336-3:2006 Method B, the closed-form root of an external gear generated by a basic rack
/// (no protuberance): §6.2 equations for E, G, H, ϑ, sFn, ρF, den, γe, αFen, hFe, YF, YS.
fn iso_method_b(g: &Involute, eps_a: f64) -> (f64, f64) {
    let mn = g.module;
    let an = g.pressure_angle;
    let bb = (g.helix.sin() * an.cos()).asin();
    let zn = g.z() / (bb.cos().powi(2) * g.helix.cos());
    let x = g.shift;
    let hfp = g.rack.dedendum * mn;
    let rhofp = g.rack.root_radius * mn;
    let e = PI / 4.0 * mn - hfp * an.tan() - (1.0 - an.sin()) * rhofp / an.cos();
    let gg = rhofp / mn - hfp / mn + x;
    let h = 2.0 / zn * (PI / 2.0 - e / mn) - PI / 3.0;
    let mut th = PI / 6.0;
    for _ in 0..50 {
        th = 2.0 * gg / zn * th.tan() - h;
    }
    let s_fn = mn * (zn * (PI / 3.0 - th).sin() + 3f64.sqrt() * (gg / th.cos() - rhofp / mn));
    let rho_f = mn * (rhofp / mn + 2.0 * gg * gg / (th.cos() * (zn * th.cos().powi(2) - 2.0 * gg)));
    let dn = mn * zn;
    let dbn = dn * an.cos();
    let dan = dn + 2.0 * (g.rack.addendum + x) * mn;
    let ean = eps_a / bb.cos().powi(2);
    let den = 2.0 * ((((dan / 2.0).powi(2) - (dbn / 2.0).powi(2)).sqrt() - PI * mn * an.cos() * (ean - 1.0)).powi(2) + (dbn / 2.0).powi(2)).sqrt();
    let aen = (dbn / den).acos();
    let ge = (0.5 * PI + 2.0 * an.tan() * x) / zn + inv(an) - inv(aen);
    let afen = aen - ge;
    let h_fe = 0.5 * mn * ((ge.cos() - ge.sin() * afen.tan()) * den / mn - zn * (PI / 3.0 - th).cos() - gg / th.cos() + rhofp / mn);
    let yf = 6.0 * h_fe / mn * afen.cos() / ((s_fn / mn).powi(2) * an.cos());
    let l = s_fn / h_fe;
    let qs = s_fn / (2.0 * rho_f);
    let ys = (1.2 + 0.13 * l) * qs.powf(1.0 / (1.21 + 2.3 / l));
    (yf, ys)
}

#[test]
fn root_form_on_the_generated_tooth_matches_iso_6336_3_method_b() {
    for (z, x, beta) in
        [(17u32, 0.0, 0.0), (20, 0.0, 0.0), (20, 0.3, 0.0), (30, -0.2, 0.0), (40, 0.0, 15.0), (50, 0.5, 0.0), (100, 0.0, 20.0), (24, 0.2, 25.0)]
    {
        let g = Involute { teeth: z, module: 3.0, shift: x, helix: f64::to_radians(beta), ..Involute::default() };
        let mate = Involute { teeth: 60, module: 3.0, helix: -g.helix, ..Involute::default() };
        let ea = mesh_external(&g, &mate, 30.0).contact_ratio;
        let rf = root_form(&g, ea, false);
        let (yf, ys) = iso_method_b(&g, ea);
        assert!(close(rf.yf, yf, 0.005), "z{z} x{x} β{beta}: YF {} vs ISO {yf}", rf.yf);
        assert!(close(rf.ys, ys, 0.005), "z{z} x{x} β{beta}: YS {} vs ISO {ys}", rf.ys);
    }
}

#[test]
fn iso_6336_2_factors_match_the_standard() {
    // ZH = 2.495 for αn = 20°, β = 0, x1 + x2 = 0 (ISO 6336-2 Figure "zone factor").
    let g = Involute::default();
    assert!((zone_factor(&g, g.alpha_t()) - 2.495).abs() < 0.002);
    // ZE = 189.8 √MPa for steel on steel (E 206 000 MPa, ν 0.3).
    assert!((elasticity_factor(Material::SteelCaseHardened, Material::SteelThroughHardened) - 189.8).abs() < 0.2);
    // Zε for spur gears: √((4 − εα)/3).
    assert!((contact_ratio_factor(1.6, 0.0) - (2.4f64 / 3.0).sqrt()).abs() < 1e-12);
    assert!((contact_ratio_factor(1.6, 1.2) - (1.0f64 / 1.6).sqrt()).abs() < 1e-12);
    // Yβ = 1 − εβ·β/120°, capped at εβ = 1, β = 30°.
    assert!((helix_factor_root(20f64.to_radians(), 0.5) - (1.0 - 0.5 * 20.0 / 120.0)).abs() < 1e-12);
    assert!((helix_factor_root(40f64.to_radians(), 2.0) - 0.75).abs() < 1e-12);
    // Life factors: static and endurance ends of ISO 6336-2's curve for case-hardened steel.
    let d = Material::SteelCaseHardened.data();
    assert!((life_factor(d.zn, 1e4) - 1.6).abs() < 1e-12);
    assert!((life_factor(d.zn, 1e9) - 1.0).abs() < 1e-12);
    let mid = life_factor(d.zn, 1e6);
    assert!(mid > 1.0 && mid < 1.6);
}

#[test]
fn lewis_form_factors_match_shigleys_table() {
    // Budynas & Nisbett, Shigley's Mechanical Engineering Design (9th ed.), Table 14-2: Lewis
    // form factor Y for 20° full-depth teeth.
    for (z, y) in [(16u32, 0.296), (20, 0.322), (30, 0.359), (50, 0.409), (100, 0.447)] {
        let g = Involute { teeth: z, module: 1.0, ..Involute::default() };
        let got = lewis_form_factor(&g);
        assert!(close(got, y, 0.05), "z{z}: Y {got} vs Shigley {y}");
    }
}

#[test]
fn shigley_example_14_1_lewis_rating() {
    // Shigley's MED (9th ed.) Example 14-1: 16 teeth, P = 8 teeth/in, F = 1.5 in, 20° full depth,
    // AISI 1020 as rolled (Sy = 30 kpsi), nd = 3, 1200 rev/min: Kv = 1.524, Wt = 364 lbf,
    // H = 6.93 hp (with Y = 0.296).
    let m = 25.4 / 8.0;
    let b = 1.5 * 25.4;
    let d = 16.0 * m;
    let v = PI * d * 1200.0 / 60_000.0; // m/s
    let kv = (6.1 + v) / 6.1; // Barth, cast profile (metric form of (1200 + V)/1200)
    assert!((kv - 1.524).abs() < 0.002);
    let sigma_all = 30.0 * 6.894_757 / 3.0; // MPa
    let wt_of = |y: f64| sigma_all * b * m * y / kv; // N
    let wt = wt_of(0.296);
    assert!(close(wt / 4.448_222, 364.0, 0.01), "{}", wt / 4.448_222);
    assert!(close(lewis_stress(wt, b, m, 0.296, kv), sigma_all, 1e-9));
    let hp = wt * v / 745.7;
    assert!(close(hp, 6.93, 0.01), "{hp}");
    // With Y measured on the generated tooth the rating lands within the table's 5 %.
    let y = lewis_form_factor(&Involute { teeth: 16, module: m, ..Involute::default() });
    assert!(close(wt_of(y) * v / 745.7, 6.93, 0.05));
}

/// A rated pair: m 2, z 20/40, b 20, 50 N·m at 1500 rpm, case-hardened steel.
fn rated_pair(torque: f64, mat: Material) -> Spec {
    let mut s = Spec::defaults_for(Kind::Pair);
    s.teeth = 20;
    s.teeth2 = 40;
    s.face_width = 20.0;
    s.load = Load { torque, speed: 1500.0, material: mat, material2: mat, ..Load::default() };
    s
}

fn fact(p: &crate::plan::Plan, label: &str) -> f64 {
    p.facts
        .iter()
        .find(|f| f.label == label)
        .unwrap_or_else(|| panic!("no fact {label}: {:?}", p.facts.iter().map(|f| &f.label).collect::<Vec<_>>()))
        .value
}

#[test]
fn pair_rating_by_hand() {
    let s = rated_pair(50.0, Material::SteelCaseHardened);
    let p = plan(&s).unwrap();
    // Ft = 2000 T / d1 = 2000 · 50 / 40.
    assert!((fact(&p, "tangential force Ft (N)") - 2500.0).abs() < 1e-9);
    assert!((fact(&p, "radial force Fr (N)") - 2500.0 * 20f64.to_radians().tan()).abs() < 1e-6);
    let v = PI * 40.0 * 1500.0 / 60_000.0;
    assert!((fact(&p, "pitch line velocity (m/s)") - v).abs() < 1e-9);
    // KV Method C, grade 7 spur: 1 + (K1/(KA·Ft/b) + K2)·z1·v/100·√(u²/(1+u²)).
    let kv = 1.0 + (26.8 / 125.0 + 0.0193) * 20.0 * v / 100.0 * (4.0f64 / 5.0).sqrt();
    assert!((fact(&p, "dynamic factor KV") - kv).abs() < 1e-9);
    // σH (gear 2, ZD = 1) = ZH·ZE·Zε·√(Ft/(d1·b)·(u+1)/u)·√KV.
    let ea = mesh_external(&Involute { teeth: 20, ..Involute::default() }, &Involute { teeth: 40, ..Involute::default() }, 20.0).contact_ratio;
    let sh = 2.495 * 189.81 * ((4.0 - ea) / 3.0).sqrt() * (2500.0 / (40.0 * 20.0) * 1.5f64).sqrt() * kv.sqrt();
    assert!(close(fact(&p, "gear 2 contact stress σH (MPa)"), sh, 0.002), "{} vs {sh}", fact(&p, "gear 2 contact stress σH (MPa)"));
    assert!(close(fact(&p, "gear 2 contact safety SH"), 1500.0 / sh, 0.002));
    // σF = Ft/(b·mn)·YF·YS·KV, against the closed-form YF·YS.
    let (yf, ys) = iso_method_b(&Involute { teeth: 20, ..Involute::default() }, ea);
    let sf = 2500.0 / 40.0 * yf * ys * kv;
    assert!(close(fact(&p, "gear 1 root stress σF (MPa)"), sf, 0.04), "{} vs {sf}", fact(&p, "gear 1 root stress σF (MPa)"));
    assert!(p.warnings.is_empty(), "{:?}", p.warnings);
}

#[test]
fn overload_warns_and_light_load_does_not() {
    let p = plan(&rated_pair(50.0, Material::Pla)).unwrap();
    assert!(p.warnings.iter().any(|w| w.contains("teeth will break")), "{:?}", p.warnings);
    assert!(p.warnings.iter().any(|w| w.contains("contact safety")));
    assert!(p.warnings.iter().any(|w| w.contains("plastic gears")));
    let p = plan(&rated_pair(0.5, Material::Pla)).unwrap();
    assert!(!p.warnings.iter().any(|w| w.contains("safety") || w.contains("break")), "{:?}", p.warnings);
    // Without a load nothing is rated.
    let p = plan(&Spec::defaults_for(Kind::Pair)).unwrap();
    assert!(!p.facts.iter().any(|f| f.label.contains("safety")));
}

#[test]
fn power_and_torque_agree() {
    let mut a = rated_pair(0.0, Material::SteelThroughHardened);
    a.load.power = 7.5;
    let t = 7.5 * 60_000.0 / (2.0 * PI * 1500.0);
    let b = rated_pair(t, Material::SteelThroughHardened);
    let (pa, pb) = (plan(&a).unwrap(), plan(&b).unwrap());
    assert!((fact(&pa, "gear 1 root stress σF (MPa)") - fact(&pb, "gear 1 root stress σF (MPa)")).abs() < 1e-9);
    let mut bad = rated_pair(0.0, Material::Pom);
    bad.load.power = 1.0;
    bad.load.speed = 0.0;
    assert!(plan(&bad).is_err());
}

#[test]
fn every_rated_kind_gives_safeties() {
    for k in [Kind::Spur, Kind::Helical, Kind::Herringbone, Kind::Internal, Kind::Pair, Kind::Planetary, Kind::Bevel, Kind::SpiralBevel, Kind::Worm] {
        let mut s = Spec::defaults_for(k);
        s.load = Load { torque: 5.0, speed: 1000.0, life_hours: 2000.0, ..Load::default() };
        if k == Kind::Worm {
            s.load.material = Material::Bronze;
        }
        let p = plan(&s).unwrap_or_else(|e| panic!("{k:?}: {e}"));
        let sf = fact(&p, "minimum bending safety SF");
        let sh = fact(&p, "minimum contact safety SH");
        assert!(sf.is_finite() && sf > 0.0 && sh.is_finite() && sh > 0.0, "{k:?}: SF {sf} SH {sh}");
        for f in &p.facts {
            assert!(f.value.is_finite(), "{k:?}: {} = {}", f.label, f.value);
        }
    }
    let mut s = Spec::defaults_for(Kind::CrossedHelical);
    s.load.torque = 2.0;
    let p = plan(&s).unwrap();
    assert!(fact(&p, "gear 1 tangential force Ft (N)") > 0.0);
    let mut s = Spec::defaults_for(Kind::Cycloidal);
    s.load.torque = 2.0;
    assert!(plan(&s).unwrap().warnings.iter().any(|w| w.contains("isn't available")));
}

#[test]
fn planets_share_the_load() {
    let mut s = Spec::defaults_for(Kind::Planetary);
    s.load = Load { torque: 10.0, speed: 1000.0, ..Load::default() };
    let p3 = plan(&s).unwrap();
    s.planets = 1;
    let mut one = s.clone();
    one.teeth = 18;
    let p1 = plan(&one).unwrap();
    // 3 planets: a third of the force times Kγ = 1.1.
    let r = fact(&p3, "sun–planet: tangential force Ft (N)") / fact(&p1, "sun–planet: tangential force Ft (N)");
    assert!((r - 1.1 / 3.0).abs() < 1e-9);
}

#[test]
fn worm_efficiency_and_self_locking() {
    // Efficiency is tan γ / tan(γ + ρ') with ρ' = atan(μ / cos αn).
    let (g, an, mu) = (10f64.to_radians(), 20f64.to_radians(), 0.05);
    let (eta, back) = worm_efficiency(g, an, mu);
    let rho = (mu / an.cos()).atan();
    assert!((eta - g.tan() / (g + rho).tan()).abs() < 0.01);
    assert!(back < eta && back > 0.0);
    // A single-start worm with a large diameter locks.
    let (_, back) = worm_efficiency(3f64.to_radians(), an, 0.08);
    assert!(back <= 0.0);
    assert!(worm_friction(0.0) == 0.15 && worm_friction(5.0) < worm_friction(0.5));
    let mut s = Spec::defaults_for(Kind::Worm);
    s.load = Load { torque: 2.0, speed: 1450.0, material: Material::Bronze, material2: Material::SteelCaseHardened, ..Load::default() };
    // Single start, q = 10: lead angle 5.7°, under the friction angle at rest (μ0 = 0.15).
    let p = plan(&s).unwrap();
    assert_eq!(fact(&p, "self-locking at rest (1 yes, 0 no)"), 1.0);
    let e1 = fact(&p, "efficiency, worm driving");
    s.starts = 2;
    let p = plan(&s).unwrap();
    assert_eq!(fact(&p, "self-locking at rest (1 yes, 0 no)"), 0.0);
    let e2 = fact(&p, "efficiency, worm driving");
    assert!(e1 > 0.5 && e2 > e1 && e2 < 0.95, "{e1} {e2}");
}
